import React, { useState, useEffect, useContext, useCallback } from 'react';
import { AuthContext } from '../../context/AuthContext';
import { useNotifications } from '../../context/NotificationContext';
import styles from './PurchaseHistory.module.css';

class InventoryManager extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            inventory: [],
            loading: true,
            error: null,
            sortField: 'purchaseDate',
            sortOrder: 'desc',
            filterStatus: '',
            searchTerm: '',
            selectedItems: [],
            showLowStock: false,
            page: 1,
            limit: 10,
            totalPages: 1
        };
    }

    componentDidMount() {
        this.fetchInventory();
    }

    componentDidUpdate(prevProps, prevState) {
        if (prevState.sortField !== this.state.sortField ||
            prevState.sortOrder !== this.state.sortOrder ||
            prevState.filterStatus !== this.state.filterStatus ||
            prevState.showLowStock !== this.state.showLowStock ||
            prevState.page !== this.state.page ||
            prevProps.supplierId !== this.props.supplierId) {
            this.fetchInventory();
        }
    }

    fetchInventory = async () => {
        this.setState({ loading: true, error: null });
        try {
            const { token } = this.props;
            const query = new URLSearchParams({
                page: this.state.page,
                limit: this.state.limit,
                sortBy: this.state.sortField,
                sortOrder: this.state.sortOrder,
                ...(this.state.filterStatus && { status: this.state.filterStatus }),
                ...(this.props.supplierId && { supplierId: this.props.supplierId })
            }).toString();

            const response = await fetch(`http://localhost:5000/api/purchases?${query}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (data.success) {
                this.setState({
                    inventory: data.data.purchases || [],
                    loading: false,
                    totalPages: data.data.pagination?.pages || 1
                });
            } else {
                throw new Error(data.message);
            }
        } catch (error) {
            this.setState({
                error: error.message,
                loading: false
            });
            this.props.showNotification('Ошибка загрузки данных', 'error');
        }
    };

    onInventoryUpdate = async (purchaseId, updates) => {
        try {
            const { token, onUpdate } = this.props;
            const response = await fetch(`http://localhost:5000/api/purchases/${purchaseId}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(updates)
            });

            const data = await response.json();
            if (data.success) {
                this.fetchInventory();
                if (onUpdate) onUpdate(data.data.purchase);
                this.props.showNotification('Закупка обновлена', 'success');
                return { success: true, message: 'Обновлено успешно' };
            } else {
                this.props.showNotification(data.message, 'error');
                return { success: false, message: data.message };
            }
        } catch (error) {
            this.props.showNotification('Ошибка обновления', 'error');
            return { success: false, message: error.message };
        }
    };

    onDeletePurchase = async (purchaseId) => {
        if (!window.confirm('Удалить эту закупку?')) return;

        try {
            const { token } = this.props;
            const response = await fetch(`http://localhost:5000/api/purchases/${purchaseId}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });

            const data = await response.json();
            if (data.success) {
                this.fetchInventory();
                this.props.showNotification('Закупка удалена', 'success');
            } else {
                this.props.showNotification(data.message, 'error');
            }
        } catch (error) {
            this.props.showNotification('Ошибка удаления', 'error');
        }
    };

    handleSort = (field) => {
        this.setState(prev => ({
            sortField: field,
            sortOrder: prev.sortField === field && prev.sortOrder === 'asc' ? 'desc' : 'asc'
        }));
    };

    handleStatusFilter = (status) => {
        this.setState({ filterStatus: status, page: 1 });
    };

    handleSearch = (e) => {
        this.setState({ searchTerm: e.target.value, page: 1 });
    };

    handleSelectItem = (purchaseId) => {
        this.setState(prev => ({
            selectedItems: prev.selectedItems.includes(purchaseId)
                ? prev.selectedItems.filter(id => id !== purchaseId)
                : [...prev.selectedItems, purchaseId]
        }));
    };

    handleSelectAll = () => {
        this.setState(prev => ({
            selectedItems: prev.selectedItems.length === prev.inventory.length
                ? []
                : prev.inventory.map(item => item._id)
        }));
    };

    handleBulkUpdate = async (status) => {
        if (this.state.selectedItems.length === 0) {
            this.props.showNotification('Выберите хотя бы одну позицию', 'warning');
            return;
        }

        if (!window.confirm(`Изменить статус ${this.state.selectedItems.length} позиций на "${status}"?`)) {
            return;
        }

        const promises = this.state.selectedItems.map(purchaseId =>
            this.onInventoryUpdate(purchaseId, { status })
        );

        try {
            const results = await Promise.all(promises);
            const successful = results.filter(r => r.success).length;
            this.props.showNotification(`Обновлено ${successful} позиций`, 'success');
            this.setState({ selectedItems: [] });
        } catch (error) {
            this.props.showNotification('Ошибка массового обновления', 'error');
        }
    };

    onDeliveryTrack = (purchaseId) => {
        const purchase = this.state.inventory.find(p => p._id === purchaseId);
        if (purchase) {
            this.props.showNotification(
                `Отслеживание доставки для заказа ${purchaseId} от поставщика ${purchase.supplier?.name}`,
                'info'
            );
        }
    };

    handlePageChange = (newPage) => {
        this.setState({ page: newPage });
    };

    handleLimitChange = (e) => {
        this.setState({ limit: parseInt(e.target.value), page: 1 });
    };

    getFilteredInventory = () => {
        const { inventory, searchTerm } = this.state;

        if (!searchTerm) return inventory;

        const searchLower = searchTerm.toLowerCase();
        return inventory.filter(item => {
            return (
                item.product?.name?.toLowerCase().includes(searchLower) ||
                item.supplier?.name?.toLowerCase().includes(searchLower) ||
                item.invoiceNumber?.toLowerCase().includes(searchLower) ||
                item._id.toLowerCase().includes(searchLower)
            );
        });
    };

    render() {
        const {
            inventory,
            loading,
            error,
            sortField,
            sortOrder,
            searchTerm,
            selectedItems,
            page,
            limit,
            totalPages
        } = this.state;

        const filteredInventory = this.getFilteredInventory();

        if (loading) return <div className={styles.loading}>Загрузка инвентаря...</div>;
        if (error) return <div className={styles.error}>{error}</div>;

        return (
            <div className={styles.inventoryManager}>
                <div className={styles.controls}>
                    <div className={styles.searchBox}>
                        <input
                            type="text"
                            placeholder="Поиск по товарам, поставщикам или ID..."
                            value={searchTerm}
                            onChange={this.handleSearch}
                            className={styles.searchInput}
                        />
                    </div>

                    <div className={styles.filterControls}>
                        <div className={styles.sortButtons}>
                            <button
                                onClick={() => this.handleSort('purchaseDate')}
                                className={`${styles.sortBtn} ${sortField === 'purchaseDate' ? styles.active : ''}`}
                            >
                                Дата {sortField === 'purchaseDate' && (sortOrder === 'asc' ? '↑' : '↓')}
                            </button>

                            <button
                                onClick={() => this.handleSort('quantity')}
                                className={`${styles.sortBtn} ${sortField === 'quantity' ? styles.active : ''}`}
                            >
                                Количество {sortField === 'quantity' && (sortOrder === 'asc' ? '↑' : '↓')}
                            </button>

                            <button
                                onClick={() => this.handleSort('purchasePrice')}
                                className={`${styles.sortBtn} ${sortField === 'purchasePrice' ? styles.active : ''}`}
                            >
                                Цена {sortField === 'purchasePrice' && (sortOrder === 'asc' ? '↑' : '↓')}
                            </button>
                        </div>

                        <div className={styles.filterSelects}>
                            <select
                                onChange={(e) => this.handleStatusFilter(e.target.value)}
                                className={styles.statusFilter}
                                value={this.state.filterStatus}
                            >
                                <option value="">Все статусы</option>
                                <option value="ordered">Заказан</option>
                                <option value="pending">В обработке</option>
                                <option value="delivered">Доставлен</option>
                                <option value="cancelled">Отменен</option>
                            </select>

                            <select
                                onChange={this.handleLimitChange}
                                value={limit}
                                className={styles.limitSelect}
                            >
                                <option value="5">5 на странице</option>
                                <option value="10">10 на странице</option>
                                <option value="20">20 на странице</option>
                                <option value="50">50 на странице</option>
                            </select>
                        </div>
                    </div>

                    {selectedItems.length > 0 && (
                        <div className={styles.bulkActions}>
                            <div className={styles.bulkInfo}>
                                <span>Выбрано: {selectedItems.length} позиций</span>
                                <button
                                    onClick={this.handleSelectAll}
                                    className={styles.selectAllBtn}
                                >
                                    {selectedItems.length === inventory.length ? 'Снять все' : 'Выбрать все'}
                                </button>
                            </div>
                            <div className={styles.bulkButtons}>
                                <button
                                    onClick={() => this.handleBulkUpdate('delivered')}
                                    className={styles.bulkDeliverBtn}
                                >
                                    Отметить доставленными
                                </button>
                                <button
                                    onClick={() => this.handleBulkUpdate('cancelled')}
                                    className={styles.bulkCancelBtn}
                                >
                                    Отменить выбранные
                                </button>
                                <button
                                    onClick={() => this.setState({ selectedItems: [] })}
                                    className={styles.clearSelectionBtn}
                                >
                                    Снять выделение
                                </button>
                            </div>
                        </div>
                    )}
                </div>

                <div className={styles.inventoryGrid}>
                    {filteredInventory.length === 0 ? (
                        <div className={styles.noResults}>
                            <p>Закупки не найдены</p>
                            {searchTerm && (
                                <p>Попробуйте изменить условия поиска</p>
                            )}
                        </div>
                    ) : (
                        filteredInventory.map(purchase => (
                            <div
                                key={purchase._id}
                                className={`${styles.inventoryCard} ${selectedItems.includes(purchase._id) ? styles.selected : ''}`}
                                onClick={() => this.handleSelectItem(purchase._id)}
                            >
                                <div className={styles.cardHeader}>
                                    <input
                                        type="checkbox"
                                        checked={selectedItems.includes(purchase._id)}
                                        onChange={() => {}}
                                        className={styles.selectCheckbox}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            this.handleSelectItem(purchase._id);
                                        }}
                                    />
                                    <div className={styles.headerInfo}>
                                        <h4>{purchase.product?.name || 'Неизвестный товар'}</h4>
                                        <div className={styles.headerMeta}>
                                            <span className={styles.purchaseId}>ID: {purchase._id.substring(0, 8)}...</span>
                                            <span className={`${styles.status} ${styles[purchase.status]}`}>
                                                {purchase.status}
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                <div className={styles.cardContent}>
                                    <div className={styles.supplierInfo}>
                                        <p className={styles.supplier}>
                                            <strong>Поставщик:</strong> {purchase.supplier?.name || 'Неизвестен'}
                                        </p>
                                        {purchase.supplier?.address?.city && (
                                            <p className={styles.city}>
                                                <strong>Город:</strong> {purchase.supplier.address.city}
                                            </p>
                                        )}
                                    </div>

                                    <div className={styles.details}>
                                        <div className={styles.detailRow}>
                                            <div className={styles.detail}>
                                                <span>Количество:</span>
                                                <span className={styles.quantity}>{purchase.quantity} шт.</span>
                                            </div>
                                            <div className={styles.detail}>
                                                <span>Цена закупки:</span>
                                                <span className={styles.price}>{purchase.purchasePrice} ₽</span>
                                            </div>
                                        </div>
                                        <div className={styles.detailRow}>
                                            <div className={styles.detail}>
                                                <span>Сумма:</span>
                                                <span className={styles.total}>
                                                    {(purchase.quantity * purchase.purchasePrice).toFixed(2)} ₽
                                                </span>
                                            </div>
                                            <div className={styles.detail}>
                                                <span>Дата заказа:</span>
                                                <span>{new Date(purchase.purchaseDate).toLocaleDateString('ru-RU')}</span>
                                            </div>
                                        </div>
                                        {purchase.deliveryDate && (
                                            <div className={styles.detail}>
                                                <span>Дата доставки:</span>
                                                <span>{new Date(purchase.deliveryDate).toLocaleDateString('ru-RU')}</span>
                                            </div>
                                        )}
                                        {purchase.invoiceNumber && (
                                            <div className={styles.detail}>
                                                <span>Накладная:</span>
                                                <span className={styles.invoice}>{purchase.invoiceNumber}</span>
                                            </div>
                                        )}
                                    </div>

                                    {purchase.notes && (
                                        <div className={styles.notes}>
                                            <strong>Примечания:</strong> {purchase.notes}
                                        </div>
                                    )}
                                </div>

                                <div className={styles.cardActions}>
                                    <button
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            this.onInventoryUpdate(purchase._id, { status: 'delivered' });
                                        }}
                                        disabled={purchase.status === 'delivered'}
                                        className={styles.deliverBtn}
                                    >
                                        {purchase.status === 'delivered' ? 'Доставлен' : 'Отметить доставленным'}
                                    </button>

                                    <button
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            this.onDeliveryTrack(purchase._id);
                                        }}
                                        className={styles.trackBtn}
                                    >
                                        Отследить
                                    </button>

                                    <button
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            this.onDeletePurchase(purchase._id);
                                        }}
                                        className={styles.deleteBtn}
                                    >
                                        Удалить
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                <div className={styles.pagination}>
                    <div className={styles.paginationInfo}>
                        <span>Страница {page} из {totalPages}</span>
                        <span>Всего: {inventory.length}</span>
                    </div>
                    <div className={styles.paginationControls}>
                        <button
                            onClick={() => this.handlePageChange(page - 1)}
                            disabled={page <= 1}
                            className={styles.pageBtn}
                        >
                            Назад
                        </button>
                        <div className={styles.pageNumbers}>
                            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                let pageNum;
                                if (totalPages <= 5) {
                                    pageNum = i + 1;
                                } else if (page <= 3) {
                                    pageNum = i + 1;
                                } else if (page >= totalPages - 2) {
                                    pageNum = totalPages - 4 + i;
                                } else {
                                    pageNum = page - 2 + i;
                                }

                                return (
                                    <button
                                        key={pageNum}
                                        onClick={() => this.handlePageChange(pageNum)}
                                        className={`${styles.pageBtn} ${page === pageNum ? styles.active : ''}`}
                                    >
                                        {pageNum}
                                    </button>
                                );
                            })}
                        </div>
                        <button
                            onClick={() => this.handlePageChange(page + 1)}
                            disabled={page >= totalPages}
                            className={styles.pageBtn}
                        >
                            Вперёд
                        </button>
                    </div>
                </div>

                <div className={styles.stats}>
                    <div className={styles.stat}>
                        <span>Всего:</span>
                        <strong>{filteredInventory.length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>Доставлено:</span>
                        <strong>{filteredInventory.filter(p => p.status === 'delivered').length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>В обработке:</span>
                        <strong>{filteredInventory.filter(p => p.status === 'pending').length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>Заказано:</span>
                        <strong>{filteredInventory.filter(p => p.status === 'ordered').length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>Общая сумма:</span>
                        <strong>
                            {filteredInventory.reduce((sum, p) => sum + (p.quantity * p.purchasePrice), 0).toFixed(2)} ₽
                        </strong>
                    </div>
                </div>
            </div>
        );
    }
}

function PurchaseHistory() {
    const { user, token } = useContext(AuthContext);
    const { showSuccess, showError, showInfo } = useNotifications();
    const [purchases, setPurchases] = useState([]);
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState(null);
    const [activeView, setActiveView] = useState('table'); // 'table' или 'inventory'

    useEffect(() => {
        if (user?.role === 'admin') {
            fetchPurchases();
            fetchStats();
        }
    }, [user]);

    const fetchPurchases = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/purchases?limit=50', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (data.success) {
                setPurchases(data.data.purchases || []);
            }
            setLoading(false);
        } catch (error) {
            console.error('Ошибка загрузки заказов:', error);
            setLoading(false);
        }
    };

    const fetchStats = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/purchases/stats', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (data.success) {
                setStats(data.data.overallStats);
            }
        } catch (error) {
            console.error('Ошибка загрузки статистики:', error);
        }
    };

    const handleStatusUpdate = async (purchaseId, newStatus) => {
        try {
            const response = await fetch(`http://localhost:5000/api/purchases/${purchaseId}/status`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ status: newStatus })
            });
            const data = await response.json();
            if (data.success) {
                fetchPurchases();
                showSuccess('Статус обновлен');
            } else {
                showError(data.message);
            }
        } catch (error) {
            showError('Ошибка обновления статуса');
        }
    };

    const showNotification = (message, type) => {
        if (type === 'success') showSuccess(message);
        else if (type === 'error') showError(message);
        else if (type === 'warning') showInfo(message);
        else showInfo(message);
    };

    const formatDate = (dateString) => {
        return new Date(dateString).toLocaleDateString('ru-RU', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    if (user?.role !== 'admin') {
        return (
            <div className={styles.accessDenied}>
                <h2>Доступ запрещен</h2>
                <p>Эта страница доступна только администраторам</p>
            </div>
        );
    }

    if (loading) {
        return <div className={styles.loading}>Загрузка истории заказов...</div>;
    }

    return (
        <div className={styles.purchaseHistory}>
            <div className={styles.header}>
                <h2 className={styles.title}>История заказов у поставщиков</h2>
                <div className={styles.viewToggle}>
                    <button
                        className={`${styles.viewBtn} ${activeView === 'table' ? styles.active : ''}`}
                        onClick={() => setActiveView('table')}
                    >
                        Таблица
                    </button>
                    <button
                        className={`${styles.viewBtn} ${activeView === 'inventory' ? styles.active : ''}`}
                        onClick={() => setActiveView('inventory')}
                    >
                        Управление инвентарем
                    </button>
                </div>
            </div>

            {stats && (
                <div className={styles.statsOverview}>
                    <div className={styles.statCard}>
                        <h3>Всего заказов</h3>
                        <p className={styles.statNumber}>{stats.totalPurchases || 0}</p>
                    </div>
                    <div className={styles.statCard}>
                        <h3>Всего товаров</h3>
                        <p className={styles.statNumber}>{stats.totalItems || 0}</p>
                    </div>
                    <div className={styles.statCard}>
                        <h3>Общая стоимость</h3>
                        <p className={styles.statNumber}>{stats.totalCost?.toFixed(2) || '0.00'} ₽</p>
                    </div>
                    <div className={styles.statCard}>
                        <h3>Средний заказ</h3>
                        <p className={styles.statNumber}>{stats.avgOrderValue?.toFixed(2) || '0.00'} ₽</p>
                    </div>
                </div>
            )}

            {activeView === 'table' ? (
                <div className={styles.tableSection}>
                    <div className={styles.tableContainer}>
                        <table className={styles.purchaseTable}>
                            <thead>
                            <tr>
                                <th>ID</th>
                                <th>Товар</th>
                                <th>Поставщик</th>
                                <th>Количество</th>
                                <th>Цена закупки</th>
                                <th>Сумма</th>
                                <th>Статус</th>
                                <th>Дата заказа</th>
                                <th>Действия</th>
                            </tr>
                            </thead>
                            <tbody>
                            {purchases.map(purchase => (
                                <tr key={purchase._id}>
                                    <td className={styles.idCell}>{purchase._id.substring(0, 8)}...</td>
                                    <td>{purchase.product?.name || 'Неизвестно'}</td>
                                    <td>{purchase.supplier?.name || 'Неизвестно'}</td>
                                    <td>{purchase.quantity}</td>
                                    <td>{purchase.purchasePrice} ₽</td>
                                    <td>{(purchase.quantity * purchase.purchasePrice).toFixed(2)} ₽</td>
                                    <td>
                                            <span className={`${styles.status} ${styles[purchase.status]}`}>
                                                {purchase.status}
                                            </span>
                                    </td>
                                    <td>{formatDate(purchase.purchaseDate)}</td>
                                    <td>
                                        <div className={styles.actionButtons}>
                                            <button
                                                onClick={() => handleStatusUpdate(purchase._id, 'delivered')}
                                                disabled={purchase.status === 'delivered'}
                                                className={styles.actionBtn}
                                            >
                                                Доставлен
                                            </button>
                                            <button
                                                onClick={() => handleStatusUpdate(purchase._id, 'cancelled')}
                                                disabled={purchase.status === 'cancelled'}
                                                className={styles.cancelBtn}
                                            >
                                                Отменить
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            ) : (
                <div className={styles.inventorySection}>
                    <h3>Управление инвентарем (классовый компонент)</h3>
                    <p className={styles.inventoryDescription}>
                        Управляйте закупками с помощью интуитивного интерфейса. Выбирайте несколько позиций для массовых операций.
                    </p>
                    <InventoryManager
                        token={token}
                        showNotification={showNotification}
                    />
                </div>
            )}
        </div>
    );
}

export default PurchaseHistory;
